    if(!alive(order.tree,NativeKind::Destructable) || destructables_.at(order.tree)->removed || !destructables_.at(order.tree)->visible || destructables_.at(order.tree)->life<=0)order.treePending=true;
    if(order.treePending){if(simulationTime_<order.repath || u->stunned() || u->rooted() || number(u->currentMoveSpeed())<=0)return;float search=direct?field("Rng",900):field("Area",900);bool any=false;auto next=reachableHarvestTree(*u,order.treePoint,search,direct,field("Rng",116),order.treeProbe,any);if(!next){u->route.clear();u->waypoint=0;if(u->carriedLumber || u->carriedGold){if(!any)order.tree=0;order.phase=GatherOrder::Phase::Return;order.repath=0;return;}if(!any){cancelGather(*u);u->currentOrder=0;}else order.repath=simulationTime_+1;return;}order.tree=next;order.treePoint=destructables_.at(next)->position;order.treePending=false;order.treeProbe=0;order.phase=GatherOrder::Phase::Approach;order.repath=0;}
