    if(direct){float value=field("DataA");if(value<0 || value>100000000 || !std::isfinite(value))throw std::runtime_error("Wisp lumber yield outside supported range");double yield=value+order.yieldRemainder;int amount=int(std::floor(yield));order.yieldRemainder=yield-amount;creditResource(u->owner,2,amount);return;}
